          }
        }
      },
      "bin-2": {
        "bin_id": "bin-2",
        "items": {
          "part]1": {
            "item_id": "part]1",
            "count": 8
          }
        }
      }
    },
    "open": true
  }
}

Task:
From bin with bin_id "bin%1", remove item with item_id "part]1". Preserve everything else.
